rawInput.command:
$root = (Resolve-Path ".").Path
Write-Output "REPO=$root"
# layout detection: canonical vs legacy direct
$canon = Get-ChildItem -LiteralPath "docs\workspaces" -Directory -ErrorAction SilentlyContinue | Where-Object { $_.Name -like "workspace-*" }
$legacy = Get-ChildItem -LiteralPath "docs" -Directory -ErrorAction SilentlyContinue | Where-Object { $_.Name -like "workspace-*" }
Write-Output "CANONICAL_COUNT=$($canon.Count)"
$canon | ForEach-Object { Write-Output "CANON=$($_.Name)" }
Write-Output "LEGACY_DIRECT_COUNT=$($legacy.Count)"
$legacy | ForEach-Object { Write-Output "LEGACY=$($_.Name)" }
# goals legacy
$goals = Test-Path -LiteralPath "docs\goals"
Write-Output "LEGACY_GOALS=$goals"
# workspace-002 candidates
$c002 = @($canon | Where-Object { $_.Name -match '^workspace-002-' })
Write-Output "MATCH_002=$($c002.Count)"
$c002 | ForEach-Object { Write-Output "MATCH=$($_.FullName)" }
# symlink / reparse check for docs and workspaces
foreach ($p in @("docs","docs\workspaces")) {
  $item = Get-Item -LiteralPath $p
  Write-Output "ATTR $p LinkType=$($item.LinkType) Target=$($item.Target) Attributes=$($item.Attributes)"
}

