rawInput.command:
function Show-Frontmatter([string]$path) {
  Write-Output "===== $path ====="
  if (-not (Test-Path -LiteralPath $path)) { Write-Output "MISSING"; return }
  $item = Get-Item -LiteralPath $path
  Write-Output "LinkType=$($item.LinkType) Attributes=$($item.Attributes)"
  $lines = Get-Content -LiteralPath $path -TotalCount 80
  $in = $false
  $n = 0
  foreach ($line in $lines) {
    $n++
    if ($n -eq 1 -and $line -eq '---') { $in = $true; Write-Output $line; continue }
    if ($in -and $line -eq '---') { Write-Output $line; break }
    if ($in) { Write-Output $line }
    if (-not $in -and $n -gt 5) { Write-Output "NO_FRONTMATTER"; break }
  }
}
